"use strict";
const fs = require("node:fs"), path = require("node:path");
const baseline = require("../backup/assets__questions.json");
const edits = new Map(), reviewedIndices = new Set(), unresolved = [];
function mark(batch) {
  const records = fs.readFileSync(path.join(__dirname, batch), "utf8").trim().split(/\r?\n/).map(JSON.parse);
  records.forEach(q => reviewedIndices.add(q.index));
}
function edit(index, changes, reason, kind = "correction", sources = []) {
  const existing = edits.get(index);
  edits.set(index, { index, changes: { ...(existing?.changes || {}), ...changes }, reason: [existing?.reason, reason].filter(Boolean).join("؛ "), kind: existing?.kind === "replacement" ? "replacement" : kind, sources: [...(existing?.sources || []), ...sources] });
}
function replace(index, Q, R, W1, W2, W3, reason, level) {
  edit(index, { Q, R, W1, W2, W3, ...(level ? { Level: level } : {}) }, reason, "replacement");
}
function level(indices, target) { indices.forEach(index => { if (baseline[index].Level !== target) edit(index, { Level: target }, "مواءمة مستوى المعرفة والاستدلال المطلوب مع قيمة السؤال", "difficulty"); }); }
function symbol(index, Q, R, W1, W2, W3, target) {
  edit(index, { Q, R, W1, W2, W3, Level: target ?? baseline[index].Level }, "جعل الرموز والتلميح كافيين لإجابة محددة واختصارها دون الاعتماد على الخيارات");
}

